/* Minimal baseline JPEG decoder for jp2a reimplementation.
 * Handles baseline (SOF0) DCT JPEGs with standard Huffman encoding.
 * Supports grayscale (1-component) and YCbCr (3-component) files,
 * with restart markers (DRI/RSTn).
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

/* JPEG markers */
#define M_SOF0 0xC0
#define M_SOF1 0xC1
#define M_SOF2 0xC2
#define M_DHT  0xC4
#define M_SOI  0xD8
#define M_EOI  0xD9
#define M_SOS  0xDA
#define M_DQT  0xDB
#define M_DRI  0xDD

typedef struct {
    int codemin[17];    /* smallest code of given length */
    int valptr[17];     /* index to values[] */
    int nbits[17];      /* number of codes per length */
    unsigned char values[256];
    int lookup[256];    /* quick lookup: for first byte -> (nbits<<8)|val for codes <= 8 bits */
    int valid;
} HuffTable;

typedef struct {
    int values[64];
    int valid;
} QuantTable;

typedef struct {
    int id;
    int h_samp, v_samp;
    int qt_id;
    int dc_id, ac_id;
    int prev_dc;
    int width, height;       /* in pixels (actual) */
    int stride;              /* row stride of buffer (in bytes) */
    int block_cols, block_rows;  /* in DCT blocks */
    unsigned char *data;     /* decoded pixel data (stride * height_padded) */
} JpegComp;

typedef struct {
    int width, height;
    int precision;
    int ncomponents;
    JpegComp comp[4];
    QuantTable qt[4];
    HuffTable dc[4];
    HuffTable ac[4];
    int restart_interval;
    int max_h, max_v;
    int mcu_w, mcu_h;
    int mcus_per_row, mcu_rows;

    FILE *fp;
    /* bit reader */
    unsigned int bitbuf;
    int bitcnt;
    int eof;
    int marker_found;
    int last_marker;
} Jpeg;

/* public image output */
typedef struct {
    int width, height;
    int components;  /* 1 or 3 */
    unsigned char *pixels;  /* width * height * components */
} JpegImage;

static const int zigzag[64] = {
     0, 1, 8,16, 9, 2, 3,10,
    17,24,32,25,18,11, 4, 5,
    12,19,26,33,40,48,41,34,
    27,20,13, 6, 7,14,21,28,
    35,42,49,56,57,50,43,36,
    29,22,15,23,30,37,44,51,
    58,59,52,45,38,31,39,46,
    53,60,61,54,47,55,62,63
};

static int read_u8(FILE *fp) { int c = fgetc(fp); return c; }
static int read_u16(FILE *fp) { int a = fgetc(fp); int b = fgetc(fp); return (a<<8)|b; }

/* Refill the bit buffer. If a marker (FF not followed by 00) is encountered,
 * set marker_found and stop. */
static void bit_refill(Jpeg *j) {
    while (j->bitcnt <= 24 && !j->marker_found) {
        int c = fgetc(j->fp);
        if (c == EOF) { j->eof = 1; return; }
        if (c == 0xFF) {
            int c2 = fgetc(j->fp);
            if (c2 == 0x00) {
                /* stuffed byte */
            } else if (c2 == EOF) {
                j->eof = 1;
                return;
            } else {
                /* real marker */
                j->marker_found = 1;
                j->last_marker = c2;
                return;
            }
        }
        j->bitbuf = (j->bitbuf << 8) | c;
        j->bitcnt += 8;
    }
}

static int get_bits(Jpeg *j, int n) {
    if (n == 0) return 0;
    if (j->bitcnt < n) bit_refill(j);
    if (j->bitcnt < n) return 0;
    int v = (j->bitbuf >> (j->bitcnt - n)) & ((1 << n) - 1);
    j->bitcnt -= n;
    return v;
}

static int peek_bits(Jpeg *j, int n) {
    if (j->bitcnt < n) bit_refill(j);
    if (j->bitcnt < n) return -1;
    return (j->bitbuf >> (j->bitcnt - n)) & ((1 << n) - 1);
}

/* Huffman decode one symbol */
static int huff_decode(Jpeg *j, HuffTable *t) {
    if (j->bitcnt < 16) bit_refill(j);
    int code = 0;
    int l;
    for (l = 1; l <= 16; l++) {
        code = (code << 1) | get_bits(j, 1);
        if (t->nbits[l] && code < t->codemin[l] + t->nbits[l]) {
            int idx = t->valptr[l] + (code - t->codemin[l]);
            return t->values[idx];
        }
    }
    return -1;
}

static int extend(int v, int nbits) {
    if (nbits == 0) return 0;
    if (v < (1 << (nbits - 1))) {
        v += (-1 << nbits) + 1;
    }
    return v;
}

static int decode_block(Jpeg *j, JpegComp *c, int *out) {
    memset(out, 0, sizeof(int) * 64);

    HuffTable *dc_t = &j->dc[c->dc_id];
    HuffTable *ac_t = &j->ac[c->ac_id];
    QuantTable *qt = &j->qt[c->qt_id];

    /* DC coefficient */
    int nbits = huff_decode(j, dc_t);
    if (nbits < 0) return -1;
    int diff = 0;
    if (nbits > 0) {
        int v = get_bits(j, nbits);
        diff = extend(v, nbits);
    }
    c->prev_dc += diff;
    out[0] = c->prev_dc * qt->values[0];

    /* AC coefficients */
    int k = 1;
    while (k < 64) {
        int sym = huff_decode(j, ac_t);
        if (sym < 0) return -1;
        if (sym == 0x00) break;  /* EOB */
        if (sym == 0xF0) { k += 16; continue; }
        int run = sym >> 4;
        int sz = sym & 0xF;
        k += run;
        if (k >= 64) break;
        int v = get_bits(j, sz);
        int val = extend(v, sz);
        int idx = zigzag[k];
        out[idx] = val * qt->values[idx];
        k++;
    }
    return 0;
}

/* IDCT (integer version based on AAN-ish approach, but simple floating IDCT here for clarity) */
static void idct(int *block, unsigned char *out, int stride) {
    float tmp[64];
    /* 1-D IDCT on rows */
    for (int i = 0; i < 8; i++) {
        float *p = tmp + i * 8;
        int *b = block + i * 8;
        if (b[1]==0 && b[2]==0 && b[3]==0 && b[4]==0 && b[5]==0 && b[6]==0 && b[7]==0) {
            float v = (float)b[0] * 0.353553390593f; /* 1/sqrt(8) * 1/sqrt(2) scale */
            /* Actually this shortcut needs proper scaling; use full IDCT to be safe */
        }
        /* full IDCT (type II inverse) */
        for (int x = 0; x < 8; x++) {
            float sum = 0;
            for (int u = 0; u < 8; u++) {
                float cu = (u == 0) ? 0.707106781187f : 1.0f;
                sum += cu * b[u] * cosf((2*x+1) * u * 3.14159265358979f / 16.0f);
            }
            p[x] = sum * 0.5f;
        }
    }
    /* 1-D IDCT on columns */
    for (int x = 0; x < 8; x++) {
        for (int y = 0; y < 8; y++) {
            float sum = 0;
            for (int v = 0; v < 8; v++) {
                float cv = (v == 0) ? 0.707106781187f : 1.0f;
                sum += cv * tmp[v*8 + x] * cosf((2*y+1) * v * 3.14159265358979f / 16.0f);
            }
            float val = sum * 0.5f + 128.0f;
            int iv = (int)(val + 0.5f);
            if (iv < 0) iv = 0;
            if (iv > 255) iv = 255;
            out[y*stride + x] = (unsigned char)iv;
        }
    }
}

static int parse_dht(Jpeg *j) {
    int len = read_u16(j->fp) - 2;
    while (len > 0) {
        int tc_th = read_u8(j->fp); len--;
        int tc = tc_th >> 4;
        int th = tc_th & 0xF;
        HuffTable *t = (tc == 0) ? &j->dc[th] : &j->ac[th];
        int total = 0;
        t->nbits[0] = 0;
        int code = 0;
        t->valptr[1] = 0;
        int ptr = 0;
        /* 16 byte counts */
        int counts[17] = {0};
        for (int i = 1; i <= 16; i++) {
            counts[i] = read_u8(j->fp); len--;
            total += counts[i];
        }
        if (total > 256) return -1;
        for (int i = 0; i < total; i++) {
            t->values[i] = read_u8(j->fp); len--;
        }
        /* Build lookup tables */
        code = 0;
        ptr = 0;
        for (int l = 1; l <= 16; l++) {
            t->nbits[l] = counts[l];
            if (counts[l] > 0) {
                t->codemin[l] = code;
                t->valptr[l] = ptr;
                ptr += counts[l];
                code += counts[l];
            } else {
                t->codemin[l] = -1;
                t->valptr[l] = ptr;
            }
            code <<= 1;
        }
        t->valid = 1;
    }
    return 0;
}

static int parse_dqt(Jpeg *j) {
    int len = read_u16(j->fp) - 2;
    while (len > 0) {
        int pq_tq = read_u8(j->fp); len--;
        int pq = pq_tq >> 4;
        int tq = pq_tq & 0xF;
        if (tq >= 4) return -1;
        for (int i = 0; i < 64; i++) {
            int v = (pq == 0) ? read_u8(j->fp) : read_u16(j->fp);
            len -= (pq == 0) ? 1 : 2;
            j->qt[tq].values[zigzag[i]] = v;
        }
        j->qt[tq].valid = 1;
    }
    return 0;
}

static int parse_sof(Jpeg *j) {
    int len = read_u16(j->fp);
    (void)len;
    j->precision = read_u8(j->fp);
    j->height = read_u16(j->fp);
    j->width = read_u16(j->fp);
    j->ncomponents = read_u8(j->fp);
    j->max_h = 0; j->max_v = 0;
    for (int i = 0; i < j->ncomponents; i++) {
        j->comp[i].id = read_u8(j->fp);
        int hv = read_u8(j->fp);
        j->comp[i].h_samp = hv >> 4;
        j->comp[i].v_samp = hv & 0xF;
        j->comp[i].qt_id = read_u8(j->fp);
        if (j->comp[i].h_samp > j->max_h) j->max_h = j->comp[i].h_samp;
        if (j->comp[i].v_samp > j->max_v) j->max_v = j->comp[i].v_samp;
    }
    j->mcu_w = j->max_h * 8;
    j->mcu_h = j->max_v * 8;
    j->mcus_per_row = (j->width + j->mcu_w - 1) / j->mcu_w;
    j->mcu_rows = (j->height + j->mcu_h - 1) / j->mcu_h;
    for (int i = 0; i < j->ncomponents; i++) {
        JpegComp *c = &j->comp[i];
        c->width = (j->width * c->h_samp + j->max_h - 1) / j->max_h;
        c->height = (j->height * c->v_samp + j->max_v - 1) / j->max_v;
        c->block_cols = j->mcus_per_row * c->h_samp;
        c->block_rows = j->mcu_rows * c->v_samp;
        c->stride = c->block_cols * 8;
        c->data = calloc((size_t)c->stride * c->block_rows * 8, 1);
        if (!c->data) return -1;
    }
    return 0;
}

static int parse_sos(Jpeg *j) {
    int len = read_u16(j->fp);
    (void)len;
    int ns = read_u8(j->fp);
    for (int i = 0; i < ns; i++) {
        int cs = read_u8(j->fp);
        int dcac = read_u8(j->fp);
        /* find component */
        int k;
        for (k = 0; k < j->ncomponents; k++) {
            if (j->comp[k].id == cs) break;
        }
        if (k == j->ncomponents) return -1;
        j->comp[k].dc_id = dcac >> 4;
        j->comp[k].ac_id = dcac & 0xF;
    }
    /* Ss, Se, Ah/Al */
    read_u8(j->fp); read_u8(j->fp); read_u8(j->fp);
    return 0;
}

static int decode_scan(Jpeg *j) {
    /* Reset DC predictors */
    for (int i = 0; i < j->ncomponents; i++) j->comp[i].prev_dc = 0;
    j->bitbuf = 0;
    j->bitcnt = 0;
    j->marker_found = 0;
    j->eof = 0;
    int mcus_total = j->mcus_per_row * j->mcu_rows;
    int mcu_count = 0;
    int restart_count = 0;

    for (int mcu_row = 0; mcu_row < j->mcu_rows; mcu_row++) {
        for (int mcu_col = 0; mcu_col < j->mcus_per_row; mcu_col++) {
            for (int ci = 0; ci < j->ncomponents; ci++) {
                JpegComp *c = &j->comp[ci];
                for (int by = 0; by < c->v_samp; by++) {
                    for (int bx = 0; bx < c->h_samp; bx++) {
                        int coef[64];
                        if (decode_block(j, c, coef) < 0) return -1;
                        int px = (mcu_col * c->h_samp + bx) * 8;
                        int py = (mcu_row * c->v_samp + by) * 8;
                        idct(coef, c->data + py * c->stride + px, c->stride);
                    }
                }
            }
            mcu_count++;
            /* Handle restart */
            if (j->restart_interval > 0) {
                restart_count++;
                if (restart_count == j->restart_interval && mcu_count < mcus_total) {
                    restart_count = 0;
                    /* Align to byte boundary */
                    j->bitcnt = 0;
                    j->bitbuf = 0;
                    /* If we already hit a marker, consume it */
                    if (!j->marker_found) {
                        /* search for RSTn marker */
                        bit_refill(j);
                    }
                    if (j->marker_found) {
                        int m = j->last_marker;
                        if (m >= 0xD0 && m <= 0xD7) {
                            j->marker_found = 0;
                        } else {
                            /* non-RST marker, end of scan */
                            return 0;
                        }
                    }
                    for (int i = 0; i < j->ncomponents; i++) j->comp[i].prev_dc = 0;
                }
            }
        }
    }
    return 0;
}

JpegImage *jpeg_decode_file(FILE *fp) {
    Jpeg j;
    memset(&j, 0, sizeof(j));
    j.fp = fp;

    int c1 = read_u8(fp);
    int c2 = read_u8(fp);
    if (c1 != 0xFF || c2 != M_SOI) return NULL;

    int sof_found = 0, sos_found = 0;
    while (!sos_found) {
        int b = read_u8(fp);
        if (b == EOF) return NULL;
        if (b != 0xFF) return NULL;
        int m;
        do { m = read_u8(fp); } while (m == 0xFF);
        if (m == EOF) return NULL;
        if (m == M_EOI) break;
        switch (m) {
            case M_SOF0: case M_SOF1:
                if (parse_sof(&j) < 0) return NULL;
                sof_found = 1;
                break;
            case M_SOF2:
                /* progressive - not fully supported here */
                return NULL;
            case M_DHT:
                if (parse_dht(&j) < 0) return NULL;
                break;
            case M_DQT:
                if (parse_dqt(&j) < 0) return NULL;
                break;
            case M_DRI: {
                int len = read_u16(fp);
                (void)len;
                j.restart_interval = read_u16(fp);
                break;
            }
            case M_SOS:
                if (parse_sos(&j) < 0) return NULL;
                sos_found = 1;
                break;
            default: {
                int len = read_u16(fp);
                for (int i = 0; i < len - 2; i++) read_u8(fp);
                break;
            }
        }
    }
    if (!sof_found) return NULL;

    if (decode_scan(&j) < 0) return NULL;

    /* Build output image */
    JpegImage *img = calloc(1, sizeof(*img));
    img->width = j.width;
    img->height = j.height;
    img->components = j.ncomponents == 1 ? 1 : 3;
    img->pixels = malloc((size_t)img->width * img->height * img->components);
    if (!img->pixels) { free(img); return NULL; }

    if (j.ncomponents == 1) {
        JpegComp *c = &j.comp[0];
        for (int y = 0; y < j.height; y++) {
            for (int x = 0; x < j.width; x++) {
                img->pixels[y * j.width + x] = c->data[y * c->stride + x];
            }
        }
    } else {
        /* YCbCr to RGB with upsampling */
        JpegComp *Y = &j.comp[0];
        JpegComp *Cb = &j.comp[1];
        JpegComp *Cr = &j.comp[2];
        for (int y = 0; y < j.height; y++) {
            for (int x = 0; x < j.width; x++) {
                /* Sample each component */
                int Yx = x, Yy = y;
                int Cbx = x * Cb->h_samp / j.max_h;
                int Cby = y * Cb->v_samp / j.max_v;
                int Crx = x * Cr->h_samp / j.max_h;
                int Cry = y * Cr->v_samp / j.max_v;
                int yy = Y->data[Yy * Y->stride + Yx];
                int cb = Cb->data[Cby * Cb->stride + Cbx] - 128;
                int cr = Cr->data[Cry * Cr->stride + Crx] - 128;
                int r = yy + (int)(1.402f * cr);
                int g = yy - (int)(0.344136f * cb + 0.714136f * cr);
                int b = yy + (int)(1.772f * cb);
                if (r < 0) r = 0; if (r > 255) r = 255;
                if (g < 0) g = 0; if (g > 255) g = 255;
                if (b < 0) b = 0; if (b > 255) b = 255;
                int idx = (y * j.width + x) * 3;
                img->pixels[idx+0] = r;
                img->pixels[idx+1] = g;
                img->pixels[idx+2] = b;
            }
        }
    }

    /* free component buffers */
    for (int i = 0; i < j.ncomponents; i++) free(j.comp[i].data);
    return img;
}

void jpeg_image_free(JpegImage *img) {
    if (img) { free(img->pixels); free(img); }
}
