#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

/* JPEG markers */
#define M_SOF0 0xC0
#define M_SOF1 0xC1
#define M_SOF2 0xC2
#define M_DHT  0xC4
#define M_SOI  0xD8
#define M_EOI  0xD9
#define M_SOS  0xDA
#define M_DQT  0xDB
#define M_DRI  0xDD

typedef struct {
    int codemin[17];    /* smallest code of given length */
    int valptr[17];     /* index to values[] */
    int nbits[17];      /* number of codes per length */
    unsigned char values[256];
    int lookup[256];    /* quick lookup: for first byte -> (nbits<<8)|val for codes <= 8 bits */
