/* jp2a reimplementation
 * Converts JPEG images to ASCII art with optional colors and HTML output.
 */
#define _XOPEN_SOURCE 700
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <termios.h>
#include <ctype.h>

#include "jpeg.c"

/* Program info */
#define VERSION "1.0.8"

/* Default options */
#define DEFAULT_CHARS "   ...',;:clodxkO0KXNWM"
#define DEFAULT_FONT_SIZE 8

/* Terminal size defaults when not detectable */
#define DEFAULT_TERM_COLS 80
#define DEFAULT_TERM_ROWS 24

/* Options structure */
typedef struct {
    int width;
    int height;
    int auto_width;     /* compute width from aspect if set */
    int auto_height;    /* compute height from aspect if set */
    int term_fit;
    int term_width;
    int term_height;
    int term_zoom;
    int border;
    int invert;
    int colors;
    int html;
    int html_raw;
    int html_no_bold;
    int html_fontsize;
    int fill;
    int grayscale;
    int flipx;
    int flipy;
    int verbose;
    int debug;
    int clear;
    int background_light; /* 0=dark, 1=light */
    char chars[256];
    int nchars;
    float red, green, blue;
    char *output_file;
    char *html_title;
} Options;

static Options opt;

static void set_defaults(void) {
    memset(&opt, 0, sizeof(opt));
    opt.term_fit = 1;
    opt.auto_width = 1;
    opt.auto_height = 1;
    opt.red = 0.2989f;
    opt.green = 0.5866f;
    opt.blue = 0.1145f;
    opt.html_fontsize = DEFAULT_FONT_SIZE;
    opt.html_title = "jp2a converted image";
    strcpy(opt.chars, DEFAULT_CHARS);
    opt.nchars = (int)strlen(DEFAULT_CHARS);
}

/* Print program version banner (to stdout) */
static void print_version(void) {
    printf("jp2a %s\n", VERSION);
    printf("Copyright 2006-2016 Christian Stigen Larsen\n");
    printf("Distributed under the GNU General Public License (GPL) v2.\n");
}

static void print_help(void) {
    print_version();
    fputs("\n", stdout);
    fputs("Usage: jp2a [ options ] [ file(s) | URL(s) ]\n", stdout);
    fputs("\n", stdout);
    fputs("Convert files or URLs from JPEG format to ASCII.\n", stdout);
    fputs("\n", stdout);
    fputs("OPTIONS\n", stdout);
    fputs("  -                 Read images from standard input.\n", stdout);
    fputs("      --blue=N.N    Set RGB to grayscale conversion weight, default is 0.1145\n", stdout);
    fputs("  -b, --border      Print a border around the output image.\n", stdout);
    fputs("      --chars=...   Select character palette used to paint the image.\n", stdout);
    fputs("                    Leftmost character corresponds to black pixel, right-\n", stdout);
    fputs("                    most to white.  Minimum two characters must be specified.\n", stdout);
    fputs("      --clear       Clears screen before drawing each output image.\n", stdout);
    fputs("      --colors      Use ANSI colors in output.\n", stdout);
    fputs("  -d, --debug       Print additional debug information.\n", stdout);
    fputs("      --fill        When used with --color and/or --html, color each character's\n", stdout);
    fputs("                    background color.\n", stdout);
    fputs("  -x, --flipx       Flip image in X direction.\n", stdout);
    fputs("  -y, --flipy       Flip image in Y direction.\n", stdout);
    fputs("  -f, --term-fit    Use the largest image dimension that fits in your terminal\n", stdout);
    fputs("                    display with correct aspect ratio.\n", stdout);
    fputs("      --term-height Use terminal display height.\n", stdout);
    fputs("      --term-width  Use terminal display width.\n", stdout);
    fputs("  -z, --term-zoom   Use terminal display dimension for output.\n", stdout);
    fputs("      --grayscale   Convert image to grayscale when using --html or --colors\n", stdout);
    fputs("      --green=N.N   Set RGB to grayscale conversion weight, default is 0.5866\n", stdout);
    fputs("      --height=N    Set output height, calculate width from aspect ratio.\n", stdout);
    fputs("  -h, --help        Print program help.\n", stdout);
    fputs("      --html        Produce strict XHTML 1.0 output.\n", stdout);
    fputs("      --html-fill   Same as --fill (will be phased out)\n", stdout);
    fputs("      --html-fontsize=N   Set fontsize to N pt, default is 4.\n", stdout);
    fputs("      --html-no-bold      Do not use bold characters with HTML output\n", stdout);
    fputs("      --html-raw    Output raw HTML codes, i.e. without the <head> section etc.\n", stdout);
    fputs("      --html-title=...  Set HTML output title\n", stdout);
    fputs("  -i, --invert      Invert output image.  Use if your display has a dark\n", stdout);
    fputs("                    background.\n", stdout);
    fputs("      --background=dark   These are just mnemonics whether to use --invert\n", stdout);
    fputs("      --background=light  or not.  If your console has light characters on\n", stdout);
    fputs("                    a dark background, use --background=dark.\n", stdout);
    fputs("      --output=...  Write output to file.\n", stdout);
    fputs("      --red=N.N     Set RGB to grayscale conversion weight, default 0.2989f.\n", stdout);
    fputs("      --size=WxH    Set output width and height.\n", stdout);
    fputs("  -v, --verbose     Verbose output.\n", stdout);
    fputs("  -V, --version     Print program version.\n", stdout);
    fputs("      --width=N     Set output width, calculate height from ratio.\n", stdout);
    fputs("\n", stdout);
    fputs("  The default mode is `jp2a --term-fit --background=dark'.\n", stdout);
    fputs("  See the man-page for jp2a for more detailed help text.\n", stdout);
    fputs("\n", stdout);
    fputs("Project homepage on https://github.com/cslarsen/jp2a\n", stdout);
    fputs("Report bugs to <csl@csl.name>\n", stdout);
}

static int starts_with(const char *s, const char *prefix) {
    return strncmp(s, prefix, strlen(prefix)) == 0;
}

/* Try to get terminal size */
static void get_term_size(int *cols, int *rows) {
    struct winsize ws;
    *cols = 0;
    *rows = 0;
    int fds[] = {1, 2, 0};
    for (int i = 0; i < 3; i++) {
        if (ioctl(fds[i], TIOCGWINSZ, &ws) == 0 && ws.ws_col > 0 && ws.ws_row > 0) {
            *cols = ws.ws_col;
            *rows = ws.ws_row;
            return;
        }
    }
    /* Fall back to env vars */
    const char *c = getenv("COLUMNS");
    const char *r = getenv("LINES");
    *cols = c ? atoi(c) : DEFAULT_TERM_COLS;
    *rows = r ? atoi(r) : DEFAULT_TERM_ROWS;
    if (*cols <= 0) *cols = DEFAULT_TERM_COLS;
    if (*rows <= 0) *rows = DEFAULT_TERM_ROWS;
}

/* Parse options; return 0 on success, negative on error, positive when
 * program should exit (for --help/--version). argv[*argi] etc. */
static int parse_options(int argc, char **argv, int *n_nonopt, char **nonopt) {
    *n_nonopt = 0;
    for (int i = 1; i < argc; i++) {
        char *a = argv[i];
        if (strcmp(a, "-") == 0) {
            nonopt[(*n_nonopt)++] = a;
        } else if (strcmp(a, "-h") == 0 || strcmp(a, "--help") == 0) {
            print_help();
            return 1;
        } else if (strcmp(a, "-V") == 0 || strcmp(a, "--version") == 0) {
            print_version();
            return 1;
        } else if (strcmp(a, "-b") == 0 || strcmp(a, "--border") == 0) {
            opt.border = 1;
        } else if (strcmp(a, "--clear") == 0) {
            opt.clear = 1;
        } else if (strcmp(a, "--colors") == 0 || strcmp(a, "--color") == 0) {
            opt.colors = 1;
        } else if (strcmp(a, "-d") == 0 || strcmp(a, "--debug") == 0) {
            opt.debug = 1;
        } else if (strcmp(a, "--fill") == 0 || strcmp(a, "--html-fill") == 0) {
            opt.fill = 1;
        } else if (strcmp(a, "-x") == 0 || strcmp(a, "--flipx") == 0) {
            opt.flipx = 1;
        } else if (strcmp(a, "-y") == 0 || strcmp(a, "--flipy") == 0) {
            opt.flipy = 1;
        } else if (strcmp(a, "-f") == 0 || strcmp(a, "--term-fit") == 0) {
            opt.term_fit = 1; opt.term_width = 0; opt.term_height = 0; opt.term_zoom = 0;
        } else if (strcmp(a, "--term-width") == 0) {
            opt.term_width = 1; opt.term_fit = 0; opt.term_height = 0; opt.term_zoom = 0;
        } else if (strcmp(a, "--term-height") == 0) {
            opt.term_height = 1; opt.term_fit = 0; opt.term_width = 0; opt.term_zoom = 0;
        } else if (strcmp(a, "-z") == 0 || strcmp(a, "--term-zoom") == 0) {
            opt.term_zoom = 1; opt.term_fit = 0; opt.term_width = 0; opt.term_height = 0;
        } else if (strcmp(a, "--zoom") == 0) {
            opt.term_zoom = 1; opt.term_fit = 0; opt.term_width = 0; opt.term_height = 0;
        } else if (strcmp(a, "--grayscale") == 0) {
            opt.grayscale = 1;
        } else if (strcmp(a, "--html") == 0) {
            opt.html = 1;
        } else if (strcmp(a, "--html-raw") == 0) {
            opt.html = 1; opt.html_raw = 1;
        } else if (strcmp(a, "--html-no-bold") == 0) {
            opt.html_no_bold = 1;
        } else if (strcmp(a, "-i") == 0 || strcmp(a, "--invert") == 0) {
            opt.invert = 1;
        } else if (strcmp(a, "-v") == 0 || strcmp(a, "--verbose") == 0) {
            opt.verbose = 1;
        } else if (strcmp(a, "--background=dark") == 0) {
            opt.background_light = 0; opt.invert = 0;
        } else if (strcmp(a, "--background=light") == 0) {
            opt.background_light = 1; opt.invert = 1;
        } else if (starts_with(a, "--blue=")) {
            opt.blue = (float)atof(a + 7);
        } else if (starts_with(a, "--green=")) {
            opt.green = (float)atof(a + 8);
        } else if (starts_with(a, "--red=")) {
            opt.red = (float)atof(a + 6);
        } else if (starts_with(a, "--chars=")) {
            strncpy(opt.chars, a + 8, sizeof(opt.chars) - 1);
            opt.chars[sizeof(opt.chars)-1] = 0;
            opt.nchars = (int)strlen(opt.chars);
            if (opt.nchars < 2) {
                fprintf(stderr, "Must specify at least two characters in --chars.\n\n");
                print_help();
                return -1;
            }
        } else if (starts_with(a, "--width=")) {
            opt.width = atoi(a + 8);
            opt.auto_width = 0;
            opt.term_fit = 0;
        } else if (starts_with(a, "--height=")) {
            opt.height = atoi(a + 9);
            opt.auto_height = 0;
            opt.term_fit = 0;
        } else if (starts_with(a, "--size=")) {
            const char *p = a + 7;
            char *x = strchr(p, 'x');
            if (!x) {
                fprintf(stderr, "Unknown option %s\n\n", a);
                print_help();
                return -1;
            }
            opt.width = atoi(p);
            opt.height = atoi(x + 1);
            opt.auto_width = 0;
            opt.auto_height = 0;
            opt.term_fit = 0;
        } else if (starts_with(a, "--output=")) {
            opt.output_file = a + 9;
        } else if (starts_with(a, "--html-title=")) {
            opt.html_title = a + 13;
        } else if (starts_with(a, "--html-fontsize=")) {
            opt.html_fontsize = atoi(a + 16);
        } else if (a[0] == '-') {
            fprintf(stderr, "Unknown option %s\n\n", a);
            print_help();
            return -1;
        } else {
            nonopt[(*n_nonopt)++] = a;
        }
    }
    return 0;
}

/* Compute output dimensions based on options and source size */
static void compute_dims(int src_w, int src_h, int *ow, int *oh) {
    int term_cols, term_rows;
    get_term_size(&term_cols, &term_rows);

    int w = 0, h = 0;

    if (opt.term_zoom) {
        w = term_cols;
        h = term_rows - 1;
    } else if (opt.term_width) {
        w = term_cols;
        h = 0;
    } else if (opt.term_height) {
        w = 0;
        h = term_rows - 1;
    } else if (opt.term_fit) {
        /* First try height = term_rows - 1; if derived width fits in term_cols, use. */
        int h2 = term_rows - 1;
        int w2 = (int)(((float)src_w / src_h) * h2 * 2.0f + 0.5f);
        if (w2 <= term_cols) {
            w = w2; h = h2;
        } else {
            w = term_cols;
            h = (int)(((float)src_h / src_w) * w / 2.0f + 0.5f);
        }
    } else {
        w = opt.width;
        h = opt.height;
        if (opt.auto_width && !opt.auto_height) {
            /* compute width from height */
            w = (int)(((float)src_w / src_h) * h * 2.0f + 0.5f);
        } else if (!opt.auto_width && opt.auto_height) {
            h = (int)(((float)src_h / src_w) * w / 2.0f + 0.5f);
        } else if (opt.auto_width && opt.auto_height) {
            /* shouldn't happen when term_fit is 0 */
        }
    }
    if (w < 1) w = 1;
    if (h < 1) h = 1;
    *ow = w;
    *oh = h;
}

/* Convert a pixel to grayscale value */
static int pixel_gray(const unsigned char *px, int components) {
    if (components == 1) return px[0];
    float g = px[0] * opt.red + px[1] * opt.green + px[2] * opt.blue;
    int iv = (int)(g + 0.5f);
    if (iv < 0) iv = 0;
    if (iv > 255) iv = 255;
    return iv;
}

/* Resize a JPEG image to the output dimensions by averaging boxes */
typedef struct {
    int width, height;
    int components;
    float *gray;  /* width * height, 0..255 */
    float *r;     /* optional: for color */
    float *g;
    float *b;
} ResizedImage;

static ResizedImage *resize_image(JpegImage *img, int ow, int oh, int need_color) {
    ResizedImage *ri = calloc(1, sizeof(*ri));
    ri->width = ow;
    ri->height = oh;
    ri->components = img->components;
    ri->gray = calloc((size_t)ow * oh, sizeof(float));
    if (need_color && img->components == 3) {
        ri->r = calloc((size_t)ow * oh, sizeof(float));
        ri->g = calloc((size_t)ow * oh, sizeof(float));
        ri->b = calloc((size_t)ow * oh, sizeof(float));
    }
    /* Box averaging with floating boundaries */
    double sx_ratio = (double)img->width / ow;
    double sy_ratio = (double)img->height / oh;
    for (int oy = 0; oy < oh; oy++) {
        int sy0 = (int)(oy * sy_ratio);
        int sy1 = (int)((oy + 1) * sy_ratio);
        if (sy1 <= sy0) sy1 = sy0 + 1;
        if (sy1 > img->height) sy1 = img->height;
        for (int ox = 0; ox < ow; ox++) {
            int sx0 = (int)(ox * sx_ratio);
            int sx1 = (int)((ox + 1) * sx_ratio);
            if (sx1 <= sx0) sx1 = sx0 + 1;
            if (sx1 > img->width) sx1 = img->width;
            double sum = 0, sumr = 0, sumg = 0, sumb = 0;
            int n = 0;
            for (int y = sy0; y < sy1; y++) {
                for (int x = sx0; x < sx1; x++) {
                    const unsigned char *p = img->pixels + (y * img->width + x) * img->components;
                    sum += pixel_gray(p, img->components);
                    if (ri->r) {
                        sumr += p[0]; sumg += p[1]; sumb += p[2];
                    }
                    n++;
                }
            }
            if (n == 0) n = 1;
            ri->gray[oy * ow + ox] = (float)(sum / n);
            if (ri->r) {
                ri->r[oy * ow + ox] = (float)(sumr / n);
                ri->g[oy * ow + ox] = (float)(sumg / n);
                ri->b[oy * ow + ox] = (float)(sumb / n);
            }
        }
    }
    return ri;
}

static void free_resized(ResizedImage *ri) {
    if (!ri) return;
    free(ri->gray);
    free(ri->r); free(ri->g); free(ri->b);
    free(ri);
}

/* Determine ANSI color code for an RGB pixel.
 * Returns a value 30..37 (foreground color). */
static int ansi_color_for_pixel(float r, float g, float b) {
    /* Threshold for considering channels "equal" */
    float maxv = r > g ? r : g; if (b > maxv) maxv = b;
    float minv = r < g ? r : g; if (b < minv) minv = b;
    float delta = maxv - minv;

    if (delta < 5.0f) {
        /* Grayscale */
        return 37; /* white */
    }
    /* Determine dominant channels */
    int R = (r >= g - 0.5f && r > b + 0.5f);
    int G = (g > r + 0.5f && g >= b - 0.5f);
    int B = (b > r + 0.5f && b > g + 0.5f);
    /* Use simple maximum approach */
    if (r >= g && r >= b) {
        /* red dominant, check if also high green -> yellow */
        if (g > b + 5.0f && g > r * 0.7f) return 33; /* yellow */
        if (b > g + 5.0f && b > r * 0.7f) return 35; /* magenta */
        return 31; /* red */
    } else if (g >= r && g >= b) {
        if (r > b + 5.0f && r > g * 0.7f) return 33; /* yellow */
        if (b > r + 5.0f && b > g * 0.7f) return 36; /* cyan */
        return 32; /* green */
    } else {
        /* b dominant */
        if (r > g + 5.0f && r > b * 0.7f) return 35; /* magenta */
        if (g > r + 5.0f && g > b * 0.7f) return 36; /* cyan */
        return 34; /* blue */
    }
    (void)R; (void)G; (void)B;
}

static int is_bold(float gray) {
    return gray > 160.0f;
}

/* Character index from intensity */
static int char_from_intensity(float gray) {
    if (gray < 0) gray = 0;
    if (gray > 255) gray = 255;
    int idx;
    if (opt.invert) {
        idx = (int)((255.0f - gray) * (opt.nchars - 1) / 255.0f + 0.5f);
    } else {
        idx = (int)(gray * (opt.nchars - 1) / 255.0f + 0.5f);
    }
    if (idx < 0) idx = 0;
    if (idx >= opt.nchars) idx = opt.nchars - 1;
    return idx;
}

/* Print a text ASCII output to file */
static void output_text(FILE *out, ResizedImage *ri) {
    int w = ri->width, h = ri->height;

    if (opt.clear) fputs("\x1b[2J\x1b[1;1H", out);

    if (opt.border) {
        fputc('+', out);
        for (int i = 0; i < w; i++) fputc('-', out);
        fputc('+', out);
        fputc('\n', out);
    }

    for (int y = 0; y < h; y++) {
        int sy = opt.flipy ? h - 1 - y : y;
        if (opt.border) fputc('|', out);
        for (int x = 0; x < w; x++) {
            int sx = opt.flipx ? w - 1 - x : x;
            float gray = ri->gray[sy * w + sx];
            int idx = char_from_intensity(gray);
            char ch = opt.chars[idx];

            if (opt.colors) {
                int color = 37;
                if (ri->r) {
                    /* use color unless grayscale flag */
                    if (!opt.grayscale)
                        color = ansi_color_for_pixel(ri->r[sy * w + sx], ri->g[sy * w + sx], ri->b[sy * w + sx]);
                }
                int bold = is_bold(gray);
                if (ri->r && !opt.grayscale) {
                    /* Output color escape */
                    if (opt.fill) fprintf(out, "\x1b[%dm%c\x1b[0m", color + 10, ch);
                    else fprintf(out, "\x1b[%dm%c\x1b[0m", color, ch);
                } else {
                    /* Grayscale: use bold for bright */
                    if (bold) fprintf(out, "\x1b[1m%c\x1b[0m", ch);
                    else fputc(ch, out);
                }
            } else {
                fputc(ch, out);
            }
        }
        if (opt.border) fputc('|', out);
        fputc('\n', out);
    }

    if (opt.border) {
        fputc('+', out);
        for (int i = 0; i < w; i++) fputc('-', out);
        fputc('+', out);
        fputc('\n', out);
    }
}

/* HTML output */
static void output_html(FILE *out, ResizedImage *ri) {
    int w = ri->width, h = ri->height;

    if (!opt.html_raw) {
        fputs("<?xml version='1.0' encoding='ISO-8859-1'?>\n", out);
        fputs("<!DOCTYPE html PUBLIC '-//W3C//DTD XHTML 1.0 Strict//EN'  'http://www.w3.org/TR/xhtml1/DTD/xhtml1-strict.dtd'>\n", out);
        fputs("<html xmlns='http://www.w3.org/1999/xhtml' lang='en' xml:lang='en'>\n", out);
        fputs("<head>\n", out);
        fprintf(out, "<title>%s</title>\n", opt.html_title);
        fputs("<style type='text/css'>\n", out);
        fputs("body {\n", out);
        if (opt.background_light) {
            fputs("   background-color: white;\n", out);
        } else {
            fputs("background-color: black;\n", out);
        }
        fputs("}\n", out);
        fputs(".ascii {\n", out);
        fputs("   font-family: Courier;\n", out);
        if (!opt.colors) {
            fprintf(out, "   color: %s;\n", opt.background_light ? "black" : "white");
        }
        fprintf(out, "   font-size:%dpt;\n", opt.html_fontsize);
        if (!opt.html_no_bold) fputs("   font-weight: bold;\n", out);
        fputs("}\n", out);
        fputs("</style>\n", out);
        fputs("</head>\n", out);
        fputs("<body>\n", out);
        fputs("<div class='ascii'><pre>\n", out);
    }

    for (int y = 0; y < h; y++) {
        int sy = opt.flipy ? h - 1 - y : y;
        for (int x = 0; x < w; x++) {
            int sx = opt.flipx ? w - 1 - x : x;
            float gray = ri->gray[sy * w + sx];
            int idx = char_from_intensity(gray);
            char ch = opt.chars[idx];
            char buf[8];
            int bl = 0;
            if (ch == '<') strcpy(buf, "&lt;"), bl = 4;
            else if (ch == '>') strcpy(buf, "&gt;"), bl = 4;
            else if (ch == '&') strcpy(buf, "&amp;"), bl = 5;
            else if (ch == '"') strcpy(buf, "&quot;"), bl = 6;
            else { buf[0] = ch; buf[1] = 0; bl = 1; }

            if (opt.colors) {
                int r, g, b;
                if (ri->r && !opt.grayscale) {
                    r = (int)(ri->r[sy * w + sx] + 0.5f);
                    g = (int)(ri->g[sy * w + sx] + 0.5f);
                    b = (int)(ri->b[sy * w + sx] + 0.5f);
                } else {
                    r = g = b = (int)(gray + 0.5f);
                }
                if (r < 0) r = 0; if (r > 255) r = 255;
                if (g < 0) g = 0; if (g > 255) g = 255;
                if (b < 0) b = 0; if (b > 255) b = 255;
                const char *attr = opt.fill ? "background-color" : "color";
                fprintf(out, "<span style='%s:#%02x%02x%02x;'>%s</span>", attr, r, g, b, buf);
            } else {
                fputs(buf, out);
            }
        }
        if (opt.html_raw || opt.colors) fputs("<br/>", out);
        fputc('\n', out);
    }

    if (!opt.html_raw) {
        fputs("</pre>\n", out);
        fputs("</div>\n", out);
        fputs("</body>\n", out);
        fputs("</html>\n", out);
    }
}

static void print_progress(int cur, int total) {
    int bars = 56;
    int done = (int)((double)cur * bars / total + 0.5);
    if (done > bars) done = bars;
    fputs("Decompressing image [", stderr);
    for (int i = 0; i < done; i++) fputc('#', stderr);
    for (int i = done; i < bars; i++) fputc('.', stderr);
    fputs("]\n", stderr);
}

/* Process a single image. Returns 0 on success. */
static int process_image(const char *filename, FILE *in, FILE *out) {
    if (opt.verbose) {
        fprintf(stderr, "File: %s\n", filename);
    }
    JpegImage *img = jpeg_decode_file(in);
    if (!img) {
        fprintf(stderr, "%s: decoding error\n", filename);
        return 1;
    }

    if (opt.verbose) {
        fprintf(stderr, "Source width: %d\n", img->width);
        fprintf(stderr, "Source height: %d\n", img->height);
        fprintf(stderr, "Source color components: %d\n", img->components);
    }

    int ow, oh;
    compute_dims(img->width, img->height, &ow, &oh);

    if (opt.verbose) {
        fprintf(stderr, "Output width: %d\n", ow);
        fprintf(stderr, "Output height: %d\n", oh);
        fprintf(stderr, "Output palette (%d chars): '%s'\n", opt.nchars, opt.chars);
    }

    /* Fake progress bar for verbose mode */
    if (opt.verbose) {
        int steps = img->height;
        for (int i = 0; i <= steps; i += (steps >= 54 ? steps/54 : 1)) {
            print_progress(i, steps);
        }
    }

    int need_color = (opt.colors || opt.html) && !opt.grayscale;
    ResizedImage *ri = resize_image(img, ow, oh, need_color);

    if (opt.html) {
        output_html(out, ri);
    } else {
        output_text(out, ri);
    }
    free_resized(ri);
    jpeg_image_free(img);
    return 0;
}

int main(int argc, char **argv) {
    set_defaults();

    char **nonopt = calloc(argc + 1, sizeof(char *));
    int n_nonopt = 0;
    int rc = parse_options(argc, argv, &n_nonopt, nonopt);
    if (rc > 0) { free(nonopt); return 0; }
    if (rc < 0) { free(nonopt); return 1; }

    if (n_nonopt == 0) {
        fprintf(stderr, "No files specified.\n\n");
        print_help();
        free(nonopt);
        return 1;
    }

    /* Check TERM env var */
    const char *term = getenv("TERM");
    if (!term || !*term) {
        fprintf(stderr, "Environment variable TERM not set.\n");
        free(nonopt);
        return 1;
    }

    FILE *out = stdout;
    if (opt.output_file && strcmp(opt.output_file, "-") != 0) {
        out = fopen(opt.output_file, "w");
        if (!out) {
            fprintf(stderr, "Could not open %s for writing\n", opt.output_file);
            free(nonopt);
            return 1;
        }
    }

    int err = 0;
    for (int i = 0; i < n_nonopt; i++) {
        const char *name = nonopt[i];
        FILE *in;
        if (strcmp(name, "-") == 0) {
            in = stdin;
            name = "-";
        } else {
            in = fopen(name, "rb");
            if (!in) {
                fprintf(stderr, "%s: cannot open file\n", name);
                err = 1;
                continue;
            }
        }
        if (process_image(name, in, out) != 0) {
            err = 1;
        }
        if (in != stdin) fclose(in);
    }

    if (out != stdout) fclose(out);
    free(nonopt);
    return err;
}
