static int starts_with(const char *s, const char *prefix) {
    return strncmp(s, prefix, strlen(prefix)) == 0;
}

/* Try to get terminal size */
static void get_term_size(int *cols, int *rows) {
    struct winsize ws;
    *cols = 0;
    *rows = 0;
    int fds[] = {1, 2, 0};
    for (int i = 0; i < 3; i++) {
        if (ioctl(fds[i], TIOCGWINSZ, &ws) == 0 && ws.ws_col > 0 && ws.ws_row > 0) {
            *cols = ws.ws_col;
            *rows = ws.ws_row;
            return;
        }
    }
    /* Fall back to env vars */
    const char *c = getenv("COLUMNS");
    const char *r = getenv("LINES");
    *cols = c ? atoi(c) : DEFAULT_TERM_COLS;
    *rows = r ? atoi(r) : DEFAULT_TERM_ROWS;
    if (*cols <= 0) *cols = DEFAULT_TERM_COLS;
    if (*rows <= 0) *rows = DEFAULT_TERM_ROWS;
}

/* Parse options; return 0 on success, negative on error, positive when
